"use client"

import { Bar, BarChart, LabelList, XAxis, YAxis } from "recharts"

import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "./card"
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "./chart"

/** One sentence on what the chart shows, the field every chart in the set exports. */
export const description = "A funnel chart with the conversion rate of each step"

const chartData = [
  { stage: "visited", label: "Visited", people: 12480, fill: "var(--color-visited)" },
  { stage: "signedUp", label: "Signed up", people: 4210, fill: "var(--color-signedUp)" },
  { stage: "activated", label: "Activated", people: 2350, fill: "var(--color-activated)" },
  { stage: "subscribed", label: "Subscribed", people: 860, fill: "var(--color-subscribed)" },
  { stage: "renewed", label: "Renewed", people: 610, fill: "var(--color-renewed)" },
]

const chartConfig = {
  people: {
    label: "People",
  },
  visited: {
    label: "Visited",
    color: "var(--chart-1)",
  },
  signedUp: {
    label: "Signed up",
    color: "var(--chart-2)",
  },
  activated: {
    label: "Activated",
    color: "var(--chart-3)",
  },
  subscribed: {
    label: "Subscribed",
    color: "var(--chart-4)",
  },
  renewed: {
    label: "Renewed",
    color: "var(--chart-5)",
  },
} satisfies ChartConfig

// Each step's rate is against the step before it, which is what a team acts on.
const steps = chartData.slice(1).map((step, index) => ({
  stage: step.stage,
  label: step.label,
  rate: (step.people / (chartData[index]?.people ?? step.people)) * 100,
}))

/** A funnel of five steps, from first visit to renewal, with each step's rate against the step before. */
export function ChartFunnel() {
  return (
    <Card>
      <CardHeader>
        <CardTitle>Funnel Chart</CardTitle>
        <CardDescription>From first visit to renewal, last 90 days</CardDescription>
      </CardHeader>
      <CardContent>
        {/* Each step is a bar as long as its count, so even a small last step keeps a readable label. */}
        <ChartContainer config={chartConfig}>
          <BarChart accessibilityLayer data={chartData} layout="vertical" margin={{ right: 48 }}>
            <YAxis
              dataKey="label"
              type="category"
              tickLine={false}
              axisLine={false}
              width={76}
            />
            <XAxis dataKey="people" type="number" hide />
            <ChartTooltip
              cursor={false}
              content={<ChartTooltipContent nameKey="stage" hideLabel />}
            />
            <Bar dataKey="people" radius={6}>
              <LabelList
                position="right"
                dataKey="people"
                formatter={(value: number) => value.toLocaleString("en-US")}
                className="fill-foreground"
                fontSize={12}
              />
            </Bar>
          </BarChart>
        </ChartContainer>
      </CardContent>
      <CardFooter className="flex-col items-start gap-2 text-sm">
        <div className="leading-none font-medium">
          {(((chartData[chartData.length - 1]?.people ?? 0) / (chartData[0]?.people ?? 1)) * 100).toFixed(1)}% of visitors renewed
        </div>
        <ol className="grid w-full grid-cols-2 gap-x-4 gap-y-1 text-muted-foreground">
          {steps.map((step) => (
            <li key={step.stage} className="flex justify-between gap-2">
              <span>{step.label}</span>
              <span className="tabular-nums">{step.rate.toFixed(1)}%</span>
            </li>
          ))}
        </ol>
      </CardFooter>
    </Card>
  )
}
